import {graduateDebtLevels as levels,graduateDebtSource as source} from './planning-graduate-debt-data.js';
export const graduateDebtDefinitions={graduateDebt:{mode:'statistics',sourceChoice:'source level',title:'Choose a study-level view of the Class of 2020 debt estimates',fields:[
  ['graduateDebtLevel','Study level: 1 all, 2 college, 3 bachelor, 4 professional, 5 master, 6 doctorate',1,1,6,1]
]}};
export function graduateDebtSelection(input){return levels[input.graduateDebtLevel-1];}
const qualityLabel=(level,key)=>level.short+' ['+level[key].quality+']';
const pairLabel=(level,mean,median)=>level.short+' ['+level[mean].quality+'/'+level[median].quality+']';
const qualityNote=' Quality codes retain the source’s estimate-specific ratings: A excellent (CV ≤5%), B very good (CV >5% to 15%), C good (CV >15% to 25%). Codes do not supply a confidence interval or establish that groups differ significantly.';
export function graduateDebtResult(kind,input){
  if(kind!=='graduateDebt')throw Error('Unknown graduate-debt topic.');
  const selected=graduateDebtSelection(input),groups=levels.slice(1),common={source:source.url,sourceLabel:'Statistics Canada · Table 37-10-0255-01 · Class of 2020, interviewed in 2023 · 2 May 2025 release'};
  return {metrics:[['Selected level: '+selected.short+' · graduates with any-source debt at graduation ['+selected.debtShare.quality+']',selected.debtShare.value/100,'percent'],['Selected level · median graduation debt among those who owed ['+selected.medianAtGrad.quality+']',selected.medianAtGrad.value,'money'],['Selected level · median debt at interview among those who still owed ['+selected.medianRemaining.quality+']',selected.medianRemaining.value,'money']],note:'Historical National Graduates Survey estimates for the Class of 2020, interviewed three years later in 2023; table released 2 May 2025 and retrieved 25 October 2026. Scope: public postsecondary institutions, graduates living in Canada at interview, Canada by province of study (national estimates include the territories), All fields of study, Total – Gender, debt to any government or non-government source. The table excludes graduates who pursued further education between graduation and interview and respondents missing level or field. The all-level aggregate overlaps its five level categories and must not be added to them. Dollar means and medians concern the stated debtor subgroup. Graduation debtors and still-owing interview debtors are not the same denominator. All estimates are rounded; A/B/C codes are retained. No individual repayment, personal borrowing target, inflation conversion, causal comparison, statistical significance or current loan balance is inferred.',charts:[
    {id:'graduate-debt-incidence',type:'bar',title:'The proportion who owed at graduation differs from the amount borrowers owed',unit:'percent',unitLabel:'Class of 2020 · percentage with debt to any source within each included level',rows:groups.map(level=>({label:qualityLabel(level,'debtShare'),value:level.debtShare.value/100})),...common,note:'Each percentage concerns all graduates included for that level, including those who owed nothing. It is not the percentage of all Canadian young adults or the share of a loan already repaid. The five categories are shown without adding the overlapping all-level aggregate.'+qualityNote},
    {id:'graduate-debt-mean-median',type:'groupbar',title:'Compare the graduation mean and median within the group that had debt',unit:'money',unitLabel:'Published CAD debt at graduation · debtors only, not all graduates',seriesNames:['Mean debt at graduation','Median debt at graduation'],rows:groups.map(level=>({label:pairLabel(level,'meanAtGrad','medianAtGrad'),values:[level.meanAtGrad.value,level.medianAtGrad.value]})),...common,note:'Both measures refer to those with debt at graduation, but summarize its distribution differently. A mean above a median does not reveal the complete distribution or an individual borrower’s amount. Row labels show quality codes in mean / median order; the full labels remain in the chart data table.'+qualityNote},
    {id:'graduate-debt-changing-subgroup',type:'groupbar',title:selected.short+': graduation debtors and those still owing at interview are different subgroups',unit:'money',unitLabel:'Published CAD debt · pay attention to the changing debtor denominator',seriesNames:['Mean debt in the stated subgroup','Median debt in the stated subgroup'],rows:[{label:'Graduation debtors ['+selected.meanAtGrad.quality+'/'+selected.medianAtGrad.quality+']',values:[selected.meanAtGrad.value,selected.medianAtGrad.value]},{label:'Still owing ['+selected.meanRemaining.quality+'/'+selected.medianRemaining.quality+']',values:[selected.meanRemaining.value,selected.medianRemaining.value]}],...common,note:'The first row includes graduates who had debt at graduation. The second row is conditional on still owing at the three-year interview. People who fully repaid are outside that second debt-amount subgroup. Subtracting these medians or means does not calculate the typical person’s repayment, and this chart never labels the difference as cash paid.'+qualityNote},
    {id:'graduate-debt-paid-off',type:'bar',title:'The paid-off proportion concerns graduates who started with debt',unit:'percent',unitLabel:'Percentage of graduation debtors who had paid it off by the interview',rows:groups.map(level=>({label:qualityLabel(level,'paidOffShare'),value:level.paidOffShare.value/100})),...common,note:'The denominator is graduates with debt at graduation in the table’s included population, rather than all graduates. These retrospective proportions are not forward probabilities of loan repayment, a schedule of monthly instalments or evidence of why one group repaid. No loan interest convention or assistance-program eligibility is inferred.'+qualityNote},
    {id:'graduate-debt-incidence-amount-map',type:'scatter',title:'Debt incidence and the borrower median describe two different dimensions',unit:'money',xUnit:'percent',xLabel:'Graduates with debt (%)',yLabel:'Median debt among graduation debtors (CAD)',pointLabelHeader:'Study level · quality [incidence / median]',pointContext:'Filled larger point: selected source level. Hollow points: other source views. The All levels point is an overlapping aggregate, not an additional disjoint population. Bracketed codes describe the incidence and median estimates, in that order. Points are historical group estimates; neither axis describes a personal forecast.',rows:levels.map(level=>({label:level.short+' ['+level.debtShare.quality+'/'+level.medianAtGrad.quality+']',x:level.debtShare.value/100,value:level.medianAtGrad.value,selected:level.id===selected.id})),...common,note:'The horizontal axis measures how common debt was among included graduates. The vertical axis measures the median amount only among debtors. A group can have a lower borrowing share and a larger debtor median. The selected point changes with the source-level control, while every observation remains fixed. No regression, causal ranking, confidence band or overall population weight is estimated.'+qualityNote},
    {id:'graduate-debt-invented-selection-example',type:'groupbar',title:'An invented example: every balance falls, while the still-owing median rises',unit:'money',unitLabel:'Original illustrative CAD balances · not survey respondents or estimates',seriesNames:['Starting debt','Later debt'],rows:[{label:'Invented borrower A: fully repays',values:[10000,0]},{label:'Invented borrower B: repays CAD 1,000',values:[20000,19000]},{label:'Invented borrower C: repays CAD 1,000',values:[30000,29000]}],note:'These three entirely invented records demonstrate selection, independently of the National Graduates Survey. The starting median across all three is CAD 20,000. Later, the two people still owing have a median of CAD 24,000, even though every borrower reduced debt. Including the paid-off zero gives a different later median of CAD 19,000. The median individual repayment is CAD 1,000. No survey microdata, interest rate, loan program or typical borrower is reconstructed.'}
  ]};
}
